def init_db():
    conn = sqlite3.connect('tour_users.db')
    conn.execute('CREATE TABLE IF NOT EXISTS users (email TEXT PRIMARY KEY, name TEXT, password TEXT)')
    conn.execute('INSERT OR IGNORE INTO users VALUES (?,?,?)', ("demo@gmail.com","Demo User","1234"))
    conn.commit(); conn.close()
init_db()

def get_user(e):
    conn = sqlite3.connect('tour_users.db'); conn.row_factory = sqlite3.Row
    cur = conn.execute('SELECT * FROM users WHERE email=?', (e.lower().strip(),)); row = cur.fetchone(); conn.close(); return row

def add_user(n,e,p):
    conn = sqlite3.connect('tour_users.db')
    try: conn.execute('INSERT INTO users VALUES (?,?,?)', (e.lower().strip(),n,p.strip())); conn.commit(); return True
    except: return False
    finally: conn.close()

def count_users():
    conn = sqlite3.connect('tour_users.db'); cur = conn.execute('SELECT COUNT(*) FROM users'); c = cur.fetchone()[0]; conn.close(); return c

def calc_dist(a,b,c,d):
    R=6371; dLat=math.radians(c-a); dLng=math.radians(d-b)
    e=math.sin(dLat/2)**2+math.cos(math.radians(a))*math.cos(math.radians(c))*math.sin(dLng/2)**2
    return R*2*math.atan2(math.sqrt(e),math.sqrt(1-e))

