def extract_city_pure_world(text):
    if not text: return None
    t=text.lower().strip()
    if 'jashelmer' in t or 'jaiselmer' in t: return "Jaisalmer"
    m=re.search(r'^([a-zA-Z\s]{2,30})\s+trip', text, re.IGNORECASE)
    if m:
        city=m.group(1).strip().title(); city=re.sub(r'\b(Mujhe|Mera|Ek|Go|To|Ka|Plan|Karo)\b','',city, flags=re.IGNORECASE).strip(); city=' '.join(city.split()[:3])
        if 2<=len(city)<=30: return city
    m1=re.search(r'([a-zA-Z\s]{2,30})\s+ka\s+trip', text, re.IGNORECASE)
    if m1:
        city=m1.group(1).strip().title(); city=re.sub(r'\b(Mujhe|Mera|Ek|Go|To|Plan|Karo)\b','',city, flags=re.IGNORECASE).strip(); city=' '.join(city.split()[:3])
        if 2<=len(city)<=30: return city
    clean=re.sub(r'\b(Tour|Trip|Plan|Days|Ka|Karo|5|4|3|Din)\b','',text, flags=re.IGNORECASE).strip().title(); clean=' '.join(clean.split()[:3])
    if 2<=len(clean)<=30: return clean
    return None

